import sys, threading, json, time, urllib.error
from http.server import BaseHTTPRequestHandler, HTTPServer
sys.path.insert(0, '.')
import importlib, weather; importlib.reload(weather)

state = {"fail": 0, "hits": 0, "code": 503}
class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def do_GET(self):
        state["hits"] += 1
        if state["hits"] <= state["fail"]:
            self.send_response(state["code"]); self.end_headers(); return
        b = json.dumps({"city": "x", "t": 20}).encode()
        self.send_response(200); self.end_headers(); self.wfile.write(b)
srv = HTTPServer(("127.0.0.1", 0), H)
threading.Thread(target=srv.serve_forever, daemon=True).start()
c = weather.WeatherClient(f"http://127.0.0.1:{srv.server_port}", backoff=0.05)

def run(fail, code=503):
    state.update(fail=fail, hits=0, code=code); t=time.time()
    try: r = c.get("x")
    except urllib.error.HTTPError as e: r = f"HTTPError {e.code}"
    return r, state["hits"], round(time.time()-t, 2)

print("ok first try:", run(0))
print("2x503 then ok:", run(2))
print("3x503:", run(3))
print("500 no retry:", run(1, 500))
srv.shutdown()

